    description: 'A powerful 300cc bike built for adventure and long-distance travel.',
    price: '₹1,90,000',
  },
};

function BikeDetails() {
  const { bikeId } = useParams();
  const bike = twoWheelerData[bikeId];

  if (!bike) {
    return <div>Bike not found!</div>;
  }

  return (
    <div className="bike-details">
      <h2>{bike.name}</h2>
      <img src={bike.image} alt={bike.name} className="bike-image" />
      <p><strong>Description:</strong> {bike.description}</p>
      <p><strong>Price:</strong> {bike.price}</p>
    </div>
  );
}

export default BikeDetails;
